def _references_source(layerdefinitions, source_name):
    if not isinstance(layerdefinitions, list):
        return False
    return any(
        isinstance(layer, dict) and layer.get("source") == source_name
        for layer in layerdefinitions
    )


def rename_node(Node, node_id, name, alias):
    Node.objects.filter(nodeid=node_id).update(name=name, alias=alias)


def update_tile_value(TileModel, node_id, old_value, new_value):
    for tile in TileModel.objects.filter(data__has_key=node_id):
        node_data = tile.data.get(node_id)
        if not isinstance(node_data, dict):
            continue
        changed = False
        for localized in node_data.values():
            if isinstance(localized, dict) and localized.get("value") == old_value:
                localized["value"] = new_value
                changed = True
        if changed:
            tile.save()


def forward(apps, schema_editor):
    Node = apps.get_model("models", "Node")
    MapSource = apps.get_model("models", "MapSource")
    MapLayer = apps.get_model("models", "MapLayer")
    TileModel = apps.get_model("models", "TileModel")

    rename_node(Node, SPRITES_NODE_ID, "MAPLIBRE_SPRITES", "maplibre_sprites")
    rename_node(Node, GLYPHS_NODE_ID, "MAPLIBRE_GLYPHS", "maplibre_glyphs")

    for name, source in NEW_MAP_SOURCES.items():
        MapSource.objects.get_or_create(name=name, defaults={"source": source})

    old_source = MapSource.objects.filter(name="mapbox-streets").first()
    if old_source and old_source.source == OLD_MAPBOX_STREETS_SOURCE:
        old_source.delete()

    streets_layer = MapLayer.objects.filter(name="streets").first()
    if streets_layer and _references_source(
        streets_layer.layerdefinitions, "mapbox-streets"
    ):
        streets_layer.layerdefinitions = NEW_STREETS_LAYERDEFS
        streets_layer.save()

    satellite_layer = MapLayer.objects.filter(name="satellite").first()
    if satellite_layer and _references_source(
        satellite_layer.layerdefinitions, "mapbox-satellite"
    ):
        satellite_layer.delete()

    satellite_source = MapSource.objects.filter(name="mapbox-satellite").first()
    if satellite_source and satellite_source.source == OLD_MAPBOX_SATELLITE_SOURCE:
        satellite_source.delete()

    update_tile_value(
        TileModel, SPRITES_NODE_ID, OLD_SPRITES_DEFAULT, NEW_SPRITES_DEFAULT
    )
    update_tile_value(TileModel, GLYPHS_NODE_ID, OLD_GLYPHS_DEFAULT, NEW_GLYPHS_DEFAULT)


def reverse(apps, schema_editor):
    Node = apps.get_model("models", "Node")
    MapSource = apps.get_model("models", "MapSource")
    MapLayer = apps.get_model("models", "MapLayer")
    TileModel = apps.get_model("models", "TileModel")

    rename_node(Node, SPRITES_NODE_ID, "MAPBOX_SPRITES", "mapbox_sprites")
    rename_node(Node, GLYPHS_NODE_ID, "MAPBOX_GLYPHS", "mapbox_glyphs")

    MapSource.objects.get_or_create(
        name="mapbox-streets", defaults={"source": OLD_MAPBOX_STREETS_SOURCE}
    )
    MapSource.objects.get_or_create(
        name="mapbox-satellite", defaults={"source": OLD_MAPBOX_SATELLITE_SOURCE}
    )
    MapSource.objects.filter(name__in=NEW_MAP_SOURCES.keys()).delete()

    MapLayer.objects.get_or_create(
        name="satellite",
        defaults={
            "layerdefinitions": OLD_SATELLITE_LAYERDEFS,
            "isoverlay": False,
            "icon": "",
            "activated": True,
            "addtomap": False,
        },
    )

    streets_layer = MapLayer.objects.filter(name="streets").first()
    if streets_layer and _references_source(streets_layer.layerdefinitions, "mtk"):
        streets_layer.layerdefinitions = OLD_STREETS_LAYERDEFS
